using Microsoft.AspNetCore.Mvc;using Microsoft.Extensions.Logging;using RandomNumbersApi.Models;using RandomNumbersApi.Services;namespace RandomNumbersApi.Controllers{[ApiController][Route("api/[controller]")]public class RandomController : ControllerBase{private readonly ILogger<RandomController> _logger;private readonly IRandomNumberService _randomService;public RandomController(ILogger<RandomController> logger, IRandomNumberService randomService){_logger = logger;_randomService = randomService;}[HttpGet]public ActionResult<RandomNumbersResponse> GetTwoRandomNumbers(){_logger.LogInformation("Generating two random numbers between 30 and 90.");var numbers = _randomService.GetTwoRandomNumbers(30, 90);var response = new RandomNumbersResponse{Numbers = numbers};return Ok(response);}}}